create table public.official_exam_versions (
  exam_id text not null,
  exam_version_id text not null,
  exam_version_path text not null,
  duration_minutes integer not null check (duration_minutes between 1 and 1440),
  question_ids text[] not null check (cardinality(question_ids) > 0),
  answer_key jsonb not null check (jsonb_typeof(answer_key) = 'object'),
  primary key (exam_id, exam_version_id),
  unique (exam_version_path)
);

revoke all on table public.official_exam_versions from public, anon, authenticated;

