create or replace function public.start_or_resume_exam_attempt(
  p_exam_id text,
  p_exam_version_id text,
  p_exam_version_path text,
  p_question_ids text[],
  p_duration_minutes integer
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_attempt public.attempts;
  v_official public.official_exam_versions;
  v_now timestamptz := clock_timestamp();
begin
  if v_user_id is null then raise exception 'Se requiere autenticación.'; end if;

  insert into public.profiles(id) values (v_user_id) on conflict (id) do nothing;
  perform 1 from public.profiles where id = v_user_id for update;

  select * into v_attempt
  from public.attempts
  where user_id = v_user_id and status = 'active' and kind = 'exam'
  for update;
  if found then
    return to_jsonb(v_attempt) || jsonb_build_object('server_now', v_now);
  end if;

  select * into v_official
  from public.official_exam_versions
  where exam_id = p_exam_id
    and exam_version_id = p_exam_version_id
    and exam_version_path = p_exam_version_path
    and question_ids = p_question_ids
    and duration_minutes = p_duration_minutes;
  if not found then
    raise exception 'El paquete no coincide con una versión oficial publicable.';
  end if;

  insert into public.attempts(
    user_id, exam_id, exam_version_id, exam_version_path, question_ids,
    kind, principal, strategy, duration_minutes, started_at, deadline_at
  ) values (
    v_user_id, v_official.exam_id, v_official.exam_version_id,
    v_official.exam_version_path, v_official.question_ids,
    'exam', false, 'exam', v_official.duration_minutes, v_now,
    v_now + make_interval(mins => v_official.duration_minutes)
  ) returning * into v_attempt;

  return to_jsonb(v_attempt) || jsonb_build_object('server_now', v_now);
end;
$$;

alter function public.finish_exam_attempt(uuid, jsonb)
  rename to finish_exam_attempt_from_official_key;
revoke all on function public.finish_exam_attempt_from_official_key(uuid, jsonb)
  from public, anon, authenticated;

create function public.finish_exam_attempt(p_attempt_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_answer_key jsonb;
begin
  if v_user_id is null then raise exception 'Se requiere autenticación.'; end if;

  select official.answer_key into v_answer_key
  from public.attempts attempt
  join public.official_exam_versions official
    on official.exam_id = attempt.exam_id
   and official.exam_version_id = attempt.exam_version_id
   and official.exam_version_path = attempt.exam_version_path
   and official.question_ids = attempt.question_ids
   and official.duration_minutes = attempt.duration_minutes
  where attempt.id = p_attempt_id
    and attempt.user_id = v_user_id
    and attempt.kind = 'exam';
  if not found then raise exception 'No existe un Modo examen oficial propio.'; end if;

  return public.finish_exam_attempt_from_official_key(p_attempt_id, v_answer_key);
end;
$$;

revoke execute on function public.finish_exam_attempt(uuid) from public, anon;
grant execute on function public.finish_exam_attempt(uuid) to authenticated;

create function public.finish_expired_exam_attempt(p_attempt_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_deadline timestamptz;
begin
  if v_user_id is null then raise exception 'Se requiere autenticación.'; end if;

  select deadline_at into v_deadline
  from public.attempts
  where id = p_attempt_id
    and user_id = v_user_id
    and kind = 'exam'
    and status = 'active';
  if not found or clock_timestamp() < v_deadline then return null; end if;

  return public.finish_exam_attempt(p_attempt_id);
end;
$$;

revoke execute on function public.finish_expired_exam_attempt(uuid) from public, anon;
grant execute on function public.finish_expired_exam_attempt(uuid) to authenticated;
